import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BM5YPQmL.js";const f=JSON.parse('{"title":"User manual","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1793465066000}'),r={name:"guide/index.md"};function n(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="user-manual" tabindex="-1">User manual <a class="header-anchor" href="#user-manual" aria-label="Permalink to &quot;User manual&quot;">​</a></h1><p>Welcome to the json-tool user manual. json-tool is a privacy-first JSON formatter, validator and beautifier. It runs entirely in your browser: none of your JSON ever leaves your machine.</p><h2 id="the-tool-at-a-glance" tabindex="-1">The tool at a glance <a class="header-anchor" href="#the-tool-at-a-glance" aria-label="Permalink to &quot;The tool at a glance&quot;">​</a></h2><p>json-tool lets you:</p><ul><li><strong>Format</strong> JSON content with a click of a button.</li><li><strong>Validate</strong> JSON and be warned about invalid content.</li><li><strong>Beautify</strong> the result with configurable indentation.</li><li>Search, clean and copy the content easily.</li><li>Inspect JSON as a <strong>table</strong>, as <strong>shape statistics</strong> and as a <strong>diff between two documents</strong>.</li></ul><h2 id="the-views" tabindex="-1">The views <a class="header-anchor" href="#the-views" aria-label="Permalink to &quot;The views&quot;">​</a></h2><p>Switch between views using the tabs in the header:</p><table tabindex="0"><thead><tr><th>View</th><th>Tab / route</th><th>Description</th></tr></thead><tbody><tr><td>Home</td><td>home tab, <code>/</code></td><td>Format and validate JSON in two editors</td></tr><tr><td>Table</td><td>table tab, <code>/table</code></td><td>See the JSON as a table</td></tr><tr><td>Shape</td><td>shape tab, <code>/schema</code></td><td>See the JSON shape and statistics</td></tr><tr><td>Diff</td><td>diff tab, <code>/diff</code></td><td>Compare two JSON documents</td></tr><tr><td>Settings</td><td>settings tab, <code>/settings</code></td><td>Configure the editors and features</td></tr></tbody></table><p>The documentation icon in the header (<strong>Docs</strong>) opens this manual in a new tab.</p><h2 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h2><p>From left to right the header shows:</p><ul><li>The <strong>JSON tool</strong> logo (goes back home) and the view tabs.</li><li>The <strong>history</strong> button (only when the JSON History feature is enabled). It opens a drawer with the JSON you have used previously.</li><li>The <strong>validate json</strong> checkbox. When on, invalid JSON is reported below the editors.</li><li>The <strong>sync scroll</strong> checkbox. When on, both editors scroll together on the same relative line.</li><li>The <strong>dark mode</strong> switch.</li></ul><h2 id="the-footer" tabindex="-1">The footer <a class="header-anchor" href="#the-footer" aria-label="Permalink to &quot;The footer&quot;">​</a></h2><p>The footer contains the license (<strong>CC0 1.0 Universal</strong>), a <strong>Found an issue?</strong> link to the GitHub issue tracker and a <strong>Buy me a coffee</strong> link.</p><h2 id="a-quick-first-run" tabindex="-1">A quick first run <a class="header-anchor" href="#a-quick-first-run" aria-label="Permalink to &quot;A quick first run&quot;">​</a></h2><ol><li>Open the app and paste or type JSON in the editor on the left.</li><li>The editor on the right shows the formatted result as you type.</li><li>Use the tabs to switch to the table view, the shape view, the diff view or the settings.</li></ol><p>Continue to the next pages for the details of every view:</p><ul><li><a href="/docs/guide/editor">Home (editor)</a></li><li><a href="/docs/guide/table">Table view</a></li><li><a href="/docs/guide/shape">Shape view</a></li><li><a href="/docs/guide/diff">Diff view</a></li><li><a href="/docs/guide/settings">Settings</a></li></ul>',18)])])}const g=t(r,[["render",n]]);export{f as __pageData,g as default};
